package cz.zamerovac.app;

import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.LongSupplier;

/** Verified publication/repair bookkeeping. A publication is never the receiver's database ACK. */
final class CloudPublications {
    static final long RECHECK_MS=24*60*60*1000L,REQUEST_MS=30*60*1000L;
    private static final Object LOCK=new Object();private static final Map<String,Long> GENERATIONS=new HashMap<>();
    private final AtomicFile file;private final String owner,namespace;private final LongSupplier clock;private JSONObject cached;private long generation=-1;
    CloudPublications(File home,String owner,String namespace)throws Exception{this(home,owner,namespace,System::currentTimeMillis);}
    CloudPublications(File home,String owner,String namespace,LongSupplier clock)throws Exception{if(!DeviceIdentity.valid(owner))throw new IOException("Neplatná identita publikace");this.owner=owner;this.namespace=PeerWire.hash(namespace.getBytes(StandardCharsets.UTF_8));this.clock=clock;file=new AtomicFile(new File(home,"sync-publications-v2-"+owner+"-"+this.namespace+".json"));}
    private JSONObject load()throws Exception{
        long current=GENERATIONS.getOrDefault(file.getBaseFile().getAbsolutePath(),0L);if(cached!=null&&generation==current)return cached;File target=file.getBaseFile();
        if(!target.exists()&&!new File(target+".bak").exists())return new JSONObject().put("version",2).put("owner",owner).put("namespace",namespace).put("blobs",new JSONObject()).put("needs",new JSONObject()).put("repairs",new JSONObject()).put("seen",new JSONObject()).put("snapshots",new JSONObject());
        if(target.length()>PeerWire.MAX_JSON||new File(target+".bak").length()>PeerWire.MAX_JSON)throw new IOException("Evidence publikací je příliš velká");JSONObject data=JsonInput.object(file.readFully());if(data.optInt("version")!=2||!owner.equals(data.optString("owner"))||!namespace.equals(data.optString("namespace")))throw new IOException("Cizí evidence publikací");if(!data.has("snapshots"))data.put("snapshots",new JSONObject());for(String key:new String[]{"blobs","needs","repairs","seen","snapshots"})if(data.getJSONObject(key).length()>100000)throw new IOException("Evidence publikací je plná");cached=data;generation=current;return data;
    }
    private void save(JSONObject data)throws Exception{
        for(String key:new String[]{"blobs","needs","repairs","seen","snapshots"})if(data.getJSONObject(key).length()>100000)throw new IOException("Evidence publikací je plná");byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>PeerWire.MAX_JSON)throw new IOException("Evidence publikací je příliš velká");FileOutputStream out=null;
        try{out=file.startWrite();out.write(bytes);out.getFD().sync();file.finishWrite(out);out=null;if(!Arrays.equals(bytes,file.readFully()))throw new IOException("Publikace nebyla místně potvrzena");long current=GENERATIONS.getOrDefault(file.getBaseFile().getAbsolutePath(),0L)+1;GENERATIONS.put(file.getBaseFile().getAbsolutePath(),current);cached=data;generation=current;}catch(Exception failure){if(out!=null)file.failWrite(out);throw failure;}
    }
    private static void hash(String hash)throws IOException{if(hash==null||!hash.matches("[a-f0-9]{64}"))throw new IOException("Neplatný hash publikace");}
    private String scope(String peer,String snapshot,String blob)throws IOException{if(!DeviceIdentity.valid(peer))throw new IOException("Neplatný partner publikace");hash(snapshot);hash(blob);return PeerWire.hash((peer+"/"+snapshot+"/"+blob).getBytes(StandardCharsets.UTF_8));}
    String fresh(String hash,long size,String round,Map<String,ImmutableStore.Entry> available)throws Exception{synchronized(LOCK){hash(hash);JSONObject receipt=load().getJSONObject("blobs").optJSONObject(hash);if(receipt==null)return null;String path=receipt.getString("path");if(!path.matches("sync/v2/blobs/"+hash+"(?:-[a-f0-9-]{36})?"))throw new IOException("Neplatná cesta ověřené publikace");long at=PeerSnapshot.integer(receipt,"at",9007199254740991L),now=clock.getAsLong();ImmutableStore.Entry entry=available.get(path.substring(path.lastIndexOf('/')+1));if(receipt.getLong("size")!=size||now<at||now-at>=RECHECK_MS||!round.isEmpty()&&!round.equals(receipt.optString("round"))||entry==null||entry.directory||entry.size>=0&&entry.size!=size)return null;return path;}}
    void published(String hash,long size,String path,String round)throws Exception{synchronized(LOCK){hash(hash);if(size<1||size>PeerSnapshot.MAX_MEDIA||path==null||!path.matches("sync/v2/blobs/"+hash+"(?:-[a-f0-9-]{36})?")||round==null||!round.isEmpty()&&!round.matches("[a-f0-9]{64}"))throw new IOException("Neplatná publikace");JSONObject data=new JSONObject(load().toString());data.getJSONObject("blobs").put(hash,new JSONObject().put("size",size).put("path",path).put("round",round).put("at",clock.getAsLong()));save(data);}}
    JSONObject need(String peer,String snapshot,long snapshotSize,String blob,long blobSize)throws Exception{synchronized(LOCK){String key=scope(peer,snapshot,blob);JSONObject data=new JSONObject(load().toString()),needs=data.getJSONObject("needs"),existing=needs.optJSONObject(key);long now=clock.getAsLong();if(existing!=null){if(existing.getLong("size")!=snapshotSize||existing.getLong("blobSize")!=blobSize)throw new IOException("Změněná neměnná žádost o opravu");if(!existing.getBoolean("sent")||now>=existing.getLong("at")&&now-existing.getLong("at")<REQUEST_MS)return new JSONObject(existing.toString());}long sequence=existing==null?1:PeerSnapshot.integer(existing,"sequence",9007199254740991L)+1;if(sequence>9007199254740991L)throw new IOException("Vyčerpané pořadí opravy");JSONObject request=CloudProof.need(owner,peer,snapshot,snapshotSize,blob,blobSize,sequence,UUID.randomUUID().toString());request.put("at",now).put("sent",false);needs.put(key,request);save(data);return new JSONObject(request.toString());}}
    void sent(String peer,String snapshot,String blob,long sequence)throws Exception{synchronized(LOCK){JSONObject data=new JSONObject(load().toString()),need=data.getJSONObject("needs").optJSONObject(scope(peer,snapshot,blob));if(need==null||need.getLong("sequence")!=sequence)throw new IOException("Zastaralá žádost o opravu");need.put("sent",true);save(data);}}
    boolean seen(String peer,String name)throws Exception{synchronized(LOCK){return load().getJSONObject("seen").has(peer+"/"+name);}}
    void observe(String peer,String name,String snapshot,String blob,long sequence)throws Exception{synchronized(LOCK){String key=scope(peer,snapshot,blob);if(name==null||!name.matches(snapshot+"-[a-f0-9-]{36}\\.json")||sequence<1||sequence>9007199254740991L)throw new IOException("Neplatná přijatá oprava");JSONObject data=new JSONObject(load().toString()),repairs=data.getJSONObject("repairs"),repair=repairs.optJSONObject(key);if(repair==null)repair=new JSONObject().put("requested",0).put("handled",0);repair.put("requested",Math.max(sequence,repair.getLong("requested")));repairs.put(key,repair);data.getJSONObject("seen").put(peer+"/"+name,true);save(data);}}
    long requested(String peer,String snapshot,String blob)throws Exception{synchronized(LOCK){JSONObject row=load().getJSONObject("repairs").optJSONObject(scope(peer,snapshot,blob));return row==null?0:PeerSnapshot.integer(row,"requested",9007199254740991L);}}
    long pending(String peer,String snapshot,String blob)throws Exception{synchronized(LOCK){JSONObject row=load().getJSONObject("repairs").optJSONObject(scope(peer,snapshot,blob));if(row==null)return 0;long requested=PeerSnapshot.integer(row,"requested",9007199254740991L);return requested>PeerSnapshot.integer(row,"handled",9007199254740991L)?requested:0;}}
    void handled(String peer,String snapshot,String blob,long sequence)throws Exception{synchronized(LOCK){JSONObject data=new JSONObject(load().toString()),row=data.getJSONObject("repairs").optJSONObject(scope(peer,snapshot,blob));if(row==null||sequence<1||sequence>row.getLong("requested"))throw new IOException("Neověřená oprava publikace");row.put("handled",Math.max(sequence,row.getLong("handled")));save(data);}}
    boolean snapshotPublished(String peer,String snapshot)throws Exception{synchronized(LOCK){JSONObject receipt=load().getJSONObject("snapshots").optJSONObject(scope(peer,snapshot,snapshot));if(receipt==null)return false;long at=PeerSnapshot.integer(receipt,"at",9007199254740991L),now=clock.getAsLong();return now>=at&&now-at<RECHECK_MS;}}
    void publishedSnapshot(String peer,String snapshot)throws Exception{synchronized(LOCK){JSONObject data=new JSONObject(load().toString());data.getJSONObject("snapshots").put(scope(peer,snapshot,snapshot),new JSONObject().put("at",clock.getAsLong()));save(data);}}
}
